pub struct ReplyMsg;

impl ReplyMsg {
    /// The literal value.
    pub const VALUE: &'static str = "reply";
}

impl Serialize for ReplyMsg {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        Self::VALUE.serialize(s)
    }
}

impl<'de> Deserialize<'de> for ReplyMsg {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let v = <String>::deserialize(d)?;
        if v == Self::VALUE {
            Ok(Self)
        } else {
            Err(serde::de::Error::custom(format!(
                "expected {:?}, found {:?}",
                Self::VALUE,
                v
            )))
        }
    }
}

/// The node is being removed or the run is ending. The process exits.
/// cddl: schema/node.cddl:221: shutdown = {
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
pub struct Shutdown {
    /// cddl: schema/node.cddl:222: msg: "shutdown",
    pub msg: ShutdownMsg,
}

impl Shutdown {
    pub fn encode(&self) -> Vec<u8> {
        serde_json::to_vec(self).expect("encode")
    }

    pub fn decode(data: &[u8]) -> Result<Self, serde_json::Error> {
        serde_json::from_slice(data)
    }
}

