/// ── Node to kernel ───────────────────────────────────────────────────────────
/// cddl: schema/node.cddl:19: kernel-message = start / advance / reply / shutdown
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum KernelMessage {
    Start(Start),
    Advance(Advance),
    Reply(Reply),
    Shutdown(Shutdown),
}

impl Default for KernelMessage {
    fn default() -> Self {
        KernelMessage::Start(Start::default())
    }
}

impl KernelMessage {
    pub fn encode(&self) -> Vec<u8> {
        serde_json::to_vec(self).expect("encode")
    }

    pub fn decode(data: &[u8]) -> Result<Self, serde_json::Error> {
        serde_json::from_slice(data)
    }
}
